-- Independent full E-engine cook; never overwrite the accepted Immersion package.
package.path='Tools/lua/?.lua;'..package.path
local ok=require('ok');local j=require('ok.json');local h=require('ok.hash');local root=ok.root:gsub('\\','/'):gsub('%s+$','');local out=root..'/output/street-social-city-production/motel-v1';local engine='E:/PhysX/UE5.8'
local function read(p)local f=assert(io.open(p,'rb'));local r=j.decode(f:read('*a'));f:close();return r end
local function write(p,r)local f=assert(io.open(p,'wb'));f:write(j.encode(r));f:close()end
local install=read(out..'/motel-install.json');local audit=read(out..'/audit.json');local routes=read(out..'/route-review.json');local map=root..'/StreetSocialCity/Content/UniversityCity/Maps/UniversityCity.umap';local sha=h.sha256_file(map);assert(install.map_sha256==sha and audit.map_sha256==sha and audit.status=='passed' and routes.map_sha256==sha and routes.status=='passed','Native motel checks must pass first')
local previous=read(root..'/output/street-social-city-production/day-night-v1/package.json');assert(previous.id=='20261024-150235' and previous.engine==engine and previous.exit_code==0);local host=previous.host;assert(host=='E:/StreetSocialCityProduction/environment-packages/20261023-145531/HostProject');local game=host..'/Binaries/Win64/StreetSocialCity.exe';local gamesha=h.sha256_file(game);assert(gamesha==previous.prebuilt_game_sha256)
local build=read(engine..'/Engine/Binaries/Win64/UnrealEditor.modules').BuildId;assert(read(host..'/Binaries/Win64/UnrealEditor.modules').BuildId==build)
local configs={};for _,name in ipairs({'DefaultEngine.ini','DefaultGame.ini'})do configs[#configs+1]={path=root..'/StreetSocialCity/Config/'..name,sha256=h.sha256_file(root..'/StreetSocialCity/Config/'..name)}end
local listing=ok.proc.run({'rg','--files','StreetSocialCity/Content/UniversityCity/MotelV1'},{capture=true,hide=true});assert(listing.code==0);local assets={};for file in listing.stdout:gmatch('[^\r\n]+')do file=file:gsub('\\','/');assert(file:match('^StreetSocialCity/Content/UniversityCity/MotelV1/') and not file:find('..',1,true));assets[#assets+1]={file=file,sha256=h.sha256_file(root..'/'..file)}end;assert(#assets>=140)
local id=os.date('%Y%m%d-%H%M%S');local target='E:/StreetSocialCityProduction/motel-packages/'..id;local cookroot='E:/StreetSocialCityProduction/motel-full-cook-'..id;local cook=cookroot..'/Windows';local log=out..'/package-'..id..'.log'
assert(ok.proc.run({'powershell.exe','-NoProfile','-Command',"if(Test-Path -LiteralPath '"..target.."'){throw 'Target already exists'};if(([IO.DriveInfo]::new('E')).AvailableFreeSpace -lt 85GB){throw 'Insufficient E space'};New-Item -ItemType Directory -Path '"..target.."' -ErrorAction Stop|Out-Null"},{hide=true}).code==0)
write(out..'/package-source-assets.json',{package_id=id,map_sha256=sha,assets=assets,configs=configs,game_sha256=gamesha});write(out..'/package-running.json',{status='running_full_cook',id=id,engine=engine,host=host,target=target,cook_output=cook,log=log,map_sha256=sha})
local args={engine..'/Engine/Binaries/ThirdParty/DotNet/10.0/win-x64/dotnet.exe',engine..'/Engine/Binaries/DotNET/AutomationTool/AutomationTool.dll','BuildCookRun','-project='..host..'/StreetSocialCity.uproject','-nop4','-utf8output','-unattended','-platform=Win64','-clientconfig=Development','-skipbuildeditor','-skipbuild','-cook','-CookOutputDir='..cook,'-skipiostore','-stage','-pak','-stagingdirectory='..target..'/Stage','-map=/Game/UniversityCity/Maps/UniversityCity','-SkipCookingEditorContent','-ubtargs=-WaitMutex','-AdditionalCookerOptions=-SkipZenStore -DDC=(Local) -LocalDataCachePath=E:/StreetSocialCityProduction/unreal-ddc/FileSystem -ini:Engine:[ConsoleVariables]:Editor.AsyncAssetCompilationMaxMemoryUsage=6'}
local r=ok.proc.run(args,{hide=true,cwd=root,stdout_file=log,stderr_file=log..'.stderr',timeout=7200});local unchanged=h.sha256_file(map)==sha and h.sha256_file(game)==gamesha;for _,c in ipairs(configs)do unchanged=unchanged and h.sha256_file(c.path)==c.sha256 end;for _,a in ipairs(assets)do unchanged=unchanged and h.sha256_file(root..'/'..a.file)==a.sha256 end
write(out..'/package.json',{status=r.code==0 and unchanged and 'built_requires_actual_game_acceptance' or 'failed',id=id,engine=engine,host=host,target=target,cook_output=cook,log=log,exit_code=r.code,map_sha256=sha,source_map_bytes_and_receipt_unchanged=unchanged,source_config_sha256=configs[1].sha256,source_game_config_sha256=configs[2].sha256,prebuilt_game_sha256=gamesha,scope='Fresh full cook to a new output and independent Stage using E engine. Earlier accepted packages and archives remain intact. Actual Game render/input/route acceptance remains required.'});assert(r.code==0 and unchanged,'Motel full cook failed: '..log)
-- The cook output (~55 GB) is only staging input; the Stage keeps the paks. Drop it so every run does not leak a full cook.
ok.proc.run({'cmd.exe','/c','rmdir','/s','/q',(cookroot:gsub('/','\\'))},{hide=true})
print('Built independent E-engine motel package '..id)
